CREATE TABLE IF NOT EXISTS new_member_products (id TEXT PRIMARY KEY, name TEXT NOT NULL, price REAL NOT NULL DEFAULT 0, image TEXT, sizes TEXT NOT NULL DEFAULT '["XS","S","M","L","XL","XXL","XXXL"]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS new_member_orders (id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, total REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'nuovo', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS new_member_order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL, product_name TEXT NOT NULL, size TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS new_member_settings (id INTEGER PRIMARY KEY, orders_enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS extra_products (id TEXT PRIMARY KEY, name TEXT NOT NULL, price REAL NOT NULL DEFAULT 0, image TEXT, sizes TEXT NOT NULL DEFAULT '["XS","S","M","L","XL","XXL","XXXL"]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS extra_orders (id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, total REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'nuovo', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS extra_order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL, product_name TEXT NOT NULL, size TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS extra_settings (id INTEGER PRIMARY KEY, orders_enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
